import{_ as a,a as i}from"./chunks/grid2.CY8b0aSp.js";import{_ as t,o as s,c as n,ae as o}from"./chunks/framework.DBosx3SP.js";const _=JSON.parse('{"title":"Scaling","description":"","frontmatter":{},"headers":[],"relativePath":"dx/scaling.md","filePath":"dx/scaling.md","lastUpdated":1792996843000}'),r={name:"dx/scaling.md"};function l(c,e,d,h,p,m){return s(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="scaling" tabindex="-1">Scaling <a class="header-anchor" href="#scaling" aria-label="Permalink to &quot;Scaling&quot;">​</a></h1><h2 id="hidpi" tabindex="-1">HiDPI <a class="header-anchor" href="#hidpi" aria-label="Permalink to &quot;HiDPI&quot;">​</a></h2><p>The library detects the current monitor&#39;s scale factor and multiplies it into all coordinates.<br> Window size specified in LogicalSize is also multiplied by SCALE_FACTOR. Window size in PhysicalSize is not.</p><h2 id="canvas-size" tabindex="-1">Canvas Size <a class="header-anchor" href="#canvas-size" aria-label="Permalink to &quot;Canvas Size&quot;">​</a></h2><p>If the canvas size gets doubled under the same resolution and scale factor, only important coordinates (axis endpoints or data points) are stretched.<br> The marker size or line thickness stays the same.</p><p>This is usually not enough for good visualization. Since we don&#39;t scale markers at all, the chart will have a lot of space and look bleak.</p><p>Example: <img src="'+a+'" alt=""> <img src="'+i+'" alt=""></p><p>In the future, we can consider the visual elements density and scale accordingly.</p><p>According to <a href="https://research.adobe.com/news/designing-responsive-visualizations/" target="_blank" rel="noreferrer">https://research.adobe.com/news/designing-responsive-visualizations/</a></p><ul><li>Most designs remove details for smaller screens rather than scale everything</li><li>Text labels abbreviate or reposition</li><li>Axes simplify, gridlines reduce</li><li>No universal scaling formula — it&#39;s about adaptive rules per element type</li></ul><h2 id="interactive-zoom" tabindex="-1">Interactive Zoom <a class="header-anchor" href="#interactive-zoom" aria-label="Permalink to &quot;Interactive Zoom&quot;">​</a></h2><p>Zoom changes the coordinate mapping and no UI.</p>',12)])])}const f=t(r,[["render",l]]);export{_ as __pageData,f as default};
